def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    # Formulas may contain deeply nested parentheses or function calls.
    if sys.getrecursionlimit() < 1_000_000:
        sys.setrecursionlimit(1_000_000)
    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)

    token_pattern = re.compile(
        r"<=|>=|<>|[A-Z][0-9]+|[A-Z]+|[0-9]+|[+\-*/(),:=<>]"
    )
    values = {}
    in_progress = set()

    def parse(text):
        tokens = token_pattern.findall(text)
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = ("binary", op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = ("binary", op, node, unary())
            return node

        def unary():
            nonlocal pos
            minus_count = 0
            while pos < len(tokens) and tokens[pos] == "-":
                minus_count += 1
                pos += 1
            node = atom()
            if minus_count % 2:
                node = ("negate", node)
            return node

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token.isdigit():
                return ("number", int(token))

            if token == "(":
                node = expression()
                pos += 1  # closing parenthesis
                return node

            if token in ("SUM", "MIN", "MAX"):
                pos += 1  # opening parenthesis
                args = []
                while True:
                    if pos + 1 < len(tokens) and tokens[pos + 1] == ":":
                        start = tokens[pos]
                        end = tokens[pos + 2]
                        args.append(("range", start, end))
                        pos += 3
                    else:
                        args.append(expression())

                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1  # comma
                return ("function", token, args)

            if token == "IF":
                pos += 1  # opening parenthesis
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # comma
                then = expression()
                pos += 1  # comma
                otherwise = expression()
                pos += 1  # closing parenthesis
                return ("if", op, left, right, then, otherwise)

            return ("reference", token)

        return expression()

    def function_items(args):
        for arg in args:
            if arg[0] != "range":
                yield arg
                continue

            start, end = arg[1], arg[2]
            first_col, last_col = sorted((ord(start[0]), ord(end[0])))
            first_row, last_row = sorted((int(start[1:]), int(end[1:])))

            for row in range(first_row, last_row + 1):
                for col in range(first_col, last_col + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def evaluate(name):
        tasks = [("cell", name)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                cell = task[1]
                if cell not in cells:
                    results.append(0)
                elif cell in values:
                    results.append(values[cell])
                elif cell in in_progress:
                    results.append("#CYCLE!")
                else:
                    in_progress.add(cell)
                    content = cells[cell]
                    tasks.append(("finish_cell", cell))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        results.append(int(content))

            elif kind == "finish_cell":
                cell = task[1]
                values[cell] = results[-1]
                in_progress.remove(cell)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "negate":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                elif node_kind == "if":
                    tasks.append(("if_left", node))
                    tasks.append(("eval", node[2]))
                else:
                    items = iter(function_items(node[2]))
                    tasks.append(("aggregate", node[1], items, None))

            elif kind == "negate":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                right = results.pop()
                op, left = task[1], task[2]
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif right == 0:
                    results.append("#DIV/0!")
                else:
                    quotient = abs(left) // abs(right)
                    results.append(-quotient if (left < 0) != (right < 0) else quotient)

            elif kind == "if_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    node = task[1]
                    tasks.append(("if_right", node, left))
                    tasks.append(("eval", node[3]))

            elif kind == "if_right":
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                else:
                    node, left = task[1], task[2]
                    op = node[1]
                    if op == "=":
                        condition = left == right
                    elif op == "<>":
                        condition = left != right
                    elif op == "<":
                        condition = left < right
                    elif op == "<=":
                        condition = left <= right
                    elif op == ">":
                        condition = left > right
                    else:
                        condition = left >= right
                    tasks.append(("eval", node[4] if condition else node[5]))

            elif kind == "aggregate":
                op, items, current = task[1], task[2], task[3]
                item = next(items, None)
                if item is None:
                    results.append(0 if current is None else current)
                else:
                    tasks.append(("aggregate_item", op, items, current))
                    tasks.append(("eval", item))

            else:  # aggregate_item
                op, items, current = task[1], task[2], task[3]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if current is None:
                        current = value
                    elif op == "SUM":
                        current += value
                    elif op == "MIN":
                        current = min(current, value)
                    else:
                        current = max(current, value)
                    tasks.append(("aggregate", op, items, current))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
